let keyPositions = [];
let foundKeys = new Set();
let usedMessage = -1;

const stickerVariants = ["cat_sticker.png", "cat_sticker_1.png", "cat_sticker_2.png", "cat_sticker_3.png", "cat_sticker_4.png", "cat_sticker_5.png", "cat_sticker_6.png", "cat_sticker_7.png", "cat_sticker_8.png"];

const stickerTransforms = [
  "rotate(-2deg) scale(1.02)",
  "rotate(2deg) scale(1.04)",
  "rotate(-1deg) scale(1.07)",
  "rotate(3deg) scale(1.01)",
  "rotate(-3deg) scale(1.05)",
  "rotate(1deg) scale(1.08)",
  "rotate(-2deg) scale(1.06)",
  "rotate(2deg) scale(1.03)"
];

function randomizeSticker() {
  if (!catSticker) return;
  const i = Math.floor(Math.random() * stickerVariants.length);
  catSticker.src = EMBEDDED_STICKERS[stickerVariants[i]];
  catSticker.style.transform = stickerTransforms[i];
  catSticker.style.transition = "transform .55s cubic-bezier(.2,.8,.2,1)";
}

function shuffle(array) {
  const a = [...array];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function randomKeyPositions() {
  return shuffle([...Array(TOTAL_BOXES).keys()]).slice(0, KEYS);
}

function speak(text) {
  if (!("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "en-US";
  utterance.rate = 0.9;
  utterance.pitch = 1.0;
  window.speechSynthesis.speak(utterance);
}

function tinySound(type) {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.frequency.value = type === "good" ? 880 : 180;
    osc.type = type === "good" ? "sine" : "triangle";
    gain.gain.setValueAtTime(0.0001, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.18);
    osc.start();
    osc.stop(ctx.currentTime + 0.2);
  } catch (_) {}
}

function updateProgress() {
  const n = foundKeys.size;
  const digits = ["٠","١","٢","٣"];
  progress.innerHTML = `🔑 کلیلە دۆزراوەکان: <b>${digits[n]} / ٣</b>`;
}

function buildGame() {
  foundKeys = new Set();
  keyPositions = randomKeyPositions();
  keyGrid.innerHTML = "";
  updateProgress();

  for (let i = 0; i < TOTAL_BOXES; i++) {
    const box = document.createElement("button");
    box.className = "key-box";
    box.type = "button";
    box.dataset.index = i;
    box.setAttribute("aria-label", `چوارچێوەی ژمارە ${i + 1}`);
    box.textContent = "♥";

    box.addEventListener("click", () => openBox(box, i));
    keyGrid.appendChild(box);
  }
}

function openBox(box, index) {
  if (box.dataset.busy === "1" || box.classList.contains("found")) return;

  box.dataset.busy = "1";
  box.classList.add("flip-open");

  const isKey = keyPositions.includes(index);

  if (isKey) {
    foundKeys.add(index);
    box.classList.add("found");
    box.textContent = "🔑";
    speak("good");
    tinySound("good");
    updateProgress();

    if (foundKeys.size === KEYS) {
      // Start the music directly from the successful user click.
      startLoveAudio();
      setTimeout(showLovePage, 520);
    } else {
      setTimeout(() => {
        box.classList.remove("flip-open");
        box.dataset.busy = "0";
      }, 520);
    }
  } else {
    box.classList.add("wrong");
    box.textContent = "×";
    speak("no");
    tinySound("no");

    // Like the supplied video: briefly opens, then closes back to the heart.
    setTimeout(() => {
      box.classList.remove("flip-open", "wrong");
      box.textContent = "♥";
      box.dataset.busy = "0";
    }, 620);
  }
}

function pickMessage() {
  let index;
  do {
    index = Math.floor(Math.random() * loveMessages.length);
  } while (loveMessages.length > 1 && index === usedMessage);
  usedMessage = index;
  loveMessage.textContent = loveMessages[index];
  randomizeSticker();
}

function startLoveAudio() {
  if (!loveAudio) return;
  if (!loveAudio.src.startsWith("data:")) loveAudio.src = EMBEDDED_AUDIO;
  loveAudio.volume = 1;
  loveAudio.muted = false;
  try { loveAudio.load(); } catch (_) {}
  loveAudio.currentTime = 0;
  // Called from the successful key click, so it has the best chance
  // of satisfying browser autoplay policies.
  const promise = loveAudio.play();
  if (promise && typeof promise.catch === "function") {
    promise.catch(() => {
      // Some browsers block audible autoplay. There is intentionally
      // no play button here, per the requested design.
    });
  }
}

function showLovePage() {
  pickMessage();
  gamePage.classList.remove("active");
  lovePage.classList.add("active");
  // Also retry when the second page becomes visible.
  startLoveAudio();
}
function showGamePage() {
  loveAudio.pause();
  loveAudio.currentTime = 0;
  lovePage.classList.remove("active");
  gamePage.classList.add("active");
  buildGame();
}

resetBtn.addEventListener("click", () => {
  buildGame();
});


backBtn.addEventListener("click", showGamePage);


buildGame();
